+
+PartitionManagerAction::PartitionManagerAction(const std::shared_ptr<StorageInfo> &storageInfo, const std::shared_ptr<StateInfo> &stateInfo, QObject *parent)
+    : ActionInterface(storageInfo, stateInfo, parent)
+    , m_partitionManager(KService::serviceByDesktopName(QStringLiteral("org.kde.partitionmanager")))
+{
+}
+
+PartitionManagerAction::~PartitionManagerAction() = default;
+
+void PartitionManagerAction::triggered()
+{
+    const Solid::Device &device = m_storageInfo->device();
+    const auto *block = device.as<Solid::Block>();
+    if (!m_partitionManager || !block || block->device().isEmpty()) {
+        return;
+    }
+
+    qCDebug(APPLETS::DEVICENOTIFIER) << "Partition Manager action: Triggered for" << block->device();
+
+    auto *job = new KIO::CommandLauncherJob(QStringLiteral("partitionmanager"), {u"--device=" + block->device()});
+    job->setDesktopName(m_partitionManager->desktopEntryName());
+    job->setUiDelegate(new KNotificationJobUiDelegate(KJobUiDelegate::AutoHandlingEnabled));
+    job->start();
+}
+
+bool PartitionManagerAction::isValid() const
+{
+    const Solid::Device &device = m_storageInfo->device();
+    // Drives without media (e.g. empty card readers) and optical drives have nothing to partition
+    const auto *drive = device.as<Solid::StorageDrive>();
+    return m_partitionManager && drive && drive->size() > 0 && !device.is<Solid::OpticalDrive>();
+}
+
+QString PartitionManagerAction::name() const
+{
+    return QStringLiteral("PartitionManager");
+}
+
+QString PartitionManagerAction::icon() const
+{
+    return QStringLiteral("partitionmanager");
+}
+
+QString PartitionManagerAction::text() const
+{
+    return i18nc("@action:button", "Open in Partition Manager");
+}
+
+#include "moc_partitionmanageraction.cpp"
