+        qCDebug(APPLETS::DEVICENOTIFIER) << "Device Controller: drive : " << udi << " has volumes. Skipping";
+        return;
+    }
+
     if (auto it = m_removeTimers.constFind(udi); it != m_removeTimers.cend()) {
         deviceDelayRemove(it->udi, it->parentUdi); // A device is removed and added back immediately, can happen during formatting
     }
@@ -212,6 +227,11 @@ void DeviceControl::onDeviceAdded(const QString &udi)
     m_devicesUdi.insert(udi);
     endInsertRows();

+    if (const QString driveUdi = storageInfo->driveUdi(); m_devicesUdi.contains(driveUdi)) {
+        qCDebug(APPLETS::DEVICENOTIFIER) << "Device Controller: drive : " << driveUdi << " got a volume. Removing the drive";
+        deviceDelayRemove(driveUdi, QString());
+    }
+
     connect(stateInfo.get(), &StateInfo::stateChanged, this, &DeviceControl::onDeviceStatusChanged);
     connect(spaceInfo.get(), &SpaceInfo::sizeChanged, this, &DeviceControl::onDeviceSizeChanged);
     connect(messageInfo.get(), &MessageInfo::messageChanged, this, &DeviceControl::onDeviceMessageChanged);
@@ -342,6 +362,8 @@ void DeviceControl::deviceDelayRemove(const QString &udi, const QString &parentU
         }
     }

+    const QString driveUdi = m_devices[position.value()].storageInfo->driveUdi();
+
     beginRemoveRows(QModelIndex(), position.value(), position.value());
     qCDebug(APPLETS::DEVICENOTIFIER) << "Device Controller: device: " << m_devices[position.value()].storageInfo->device().udi()
                                      << " successfully removed from the model";
@@ -349,6 +371,11 @@ void DeviceControl::deviceDelayRemove(const QString &udi, const QString &parentU
     m_devicesUdi.remove(udi);
     endRemoveRows();

+    // The drive's last volume is gone (e.g. its partitions were deleted), so the drive itself may need to be listed
+    if (!driveUdi.isEmpty() && !hasDriveVolumes(driveUdi)) {
+        driveDelayAdd(driveUdi);
+    }
+
     if (auto it = m_removeTimers.find(udi); it != m_removeTimers.end()) {
         if (it->timer->isActive()) {
             qCDebug(APPLETS::DEVICENOTIFIER) << "Device Controller: device " << udi << " Timer was active: stop";
@@ -371,6 +398,21 @@ void DeviceControl::onDeviceSizeChanged(const QString &udi)
     }
 }

+void DeviceControl::driveDelayAdd(const QString &udi)
+{
+    // A new drive's volumes show up right after it, wait for them before deciding whether to list the drive
+    QTimer::singleShot(DRIVE_ADD_INTERVAL, this, [this, udi] {
+        onDeviceAdded(udi);
+    });
+}
+
+bool DeviceControl::hasDriveVolumes(const QString &driveUdi) const
+{
+    return std::ranges::any_of(m_devices, [&driveUdi](const DeviceInfo &deviceInfo) {
+        return deviceInfo.storageInfo->driveUdi() == driveUdi;
+    });
+}
